export interface FetchResult {
  url: string;
  status: number;
  data: string;
}

export function fetchUrl(
  url: string,
  callback: (err: Error | null, result?: FetchResult) => void
): void {
  // Callback-based mock fetcher
  setTimeout(() => {
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
      callback(new Error(`Invalid URL: ${url}`));
      return;
    }
    if (url.includes('error')) {
      callback(new Error(`HTTP 500: Server Error fetching ${url}`));
      return;
    }
    callback(null, {
      url,
      status: 200,
      data: JSON.stringify({ id: 1, name: 'Sample Payload', url }),
    });
  }, 10);
}

import { FetchResult } from './fetcher';

export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export function transformData(
  fetchResult: FetchResult,
  callback: (err: Error | null, result?: TransformResult) => void
): void {
  setTimeout(() => {
    try {
      const parsed = JSON.parse(fetchResult.data);
      if (!parsed.name) {
        callback(new Error('Missing required field: name'));
        return;
      }
      callback(null, {
        id: parsed.id ?? Date.now(),
        slug: parsed.name.toLowerCase().replace(/\s+/g, '-'),
        sourceUrl: fetchResult.url,
        transformedAt: new Date().toISOString(),
      });
    } catch (e) {
      callback(new Error(`JSON parse failure: ${(e as Error).message}`));
    }
  }, 10);
}

import { TransformResult } from './transformer';

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export function loadRecord(
  tableName: string,
  record: TransformResult,
  callback: (err: Error | null, result?: LoadResult) => void
): void {
  setTimeout(() => {
    if (!tableName) {
      callback(new Error('Missing destination table name'));
      return;
    }
    if (record.id < 0) {
      callback(new Error(`Duplicate key violation in table ${tableName}: ${record.id}`));
      return;
    }
    callback(null, {
      insertedId: record.id,
      table: tableName,
      success: true,
    });
  }, 10);
}

import { fetchUrl, FetchResult } from './fetcher';
import { transformData, TransformResult } from './transformer';
import { loadRecord, LoadResult } from './loader';

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export function runPipeline(
  config: PipelineConfig,
  callback: (err: Error | null, result?: { fetch: FetchResult; transform: TransformResult; load: LoadResult }) => void
): void {
  // Nested callback hell
  fetchUrl(config.url, (fetchErr, fetchRes) => {
    if (fetchErr || !fetchRes) {
      callback(fetchErr ?? new Error('Fetch failed'));
      return;
    }

    transformData(fetchRes, (transErr, transRes) => {
      if (transErr || !transRes) {
        callback(transErr ?? new Error('Transform failed'));
        return;
      }

      loadRecord(config.tableName, transRes, (loadErr, loadRes) => {
        if (loadErr || !loadRes) {
          callback(loadErr ?? new Error('Load failed'));
          return;
        }

        callback(null, {
          fetch: fetchRes,
          transform: transRes,
          load: loadRes,
        });
      });
    });
  });
}

