import { FetchResult, TransformResult, TransformError } from './types';

export type { TransformResult };
export { TransformError };

export async function transformData(
  fetchResult: FetchResult,
  callback?: (err: Error | null, result?: TransformResult) => void
): Promise<TransformResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        if (!fetchResult || fetchResult.data === null || fetchResult.data === undefined) {
          throw new TransformError('Payload data is null or undefined', 'data', 'string');
        }

        let parsed: unknown;
        try {
          parsed = JSON.parse(fetchResult.data);
        } catch (e) {
          throw new TransformError(`JSON parse failure: ${(e as Error).message}`, 'data', 'json');
        }

        if (parsed === null || typeof parsed !== 'object') {
          throw new TransformError('Payload must be a non-null object', 'payload', 'object');
        }

        const record = parsed as Record<string, unknown>;

        if (!('name' in record) || record.name === undefined || record.name === null) {
          throw new TransformError('Missing required field: name', 'name', 'string');
        }

        if (typeof record.name !== 'string') {
          throw new TransformError(
            `Field "name" expected string, got ${typeof record.name}`,
            'name',
            'string'
          );
        }

        if (
          'id' in record &&
          record.id !== undefined &&
          record.id !== null &&
          typeof record.id !== 'number'
        ) {
          throw new TransformError(
            `Field "id" expected number, got ${typeof record.id}`,
            'id',
            'number'
          );
        }

        const id = typeof record.id === 'number' ? record.id : Date.now();
        const slug = record.name.toLowerCase().replace(/\s+/g, '-');

        const result: TransformResult = {
          id,
          slug,
          sourceUrl: fetchResult.url,
          transformedAt: new Date().toISOString(),
        };

        callback?.(null, result);
        resolve(result);
      } catch (err) {
        callback?.(err as Error);
        reject(err);
      }
    }, 10);
  });
}

export const transform = transformData;

