import { describe, it, expect, vi, beforeEach } from 'vitest';
import { fetchUrl, FetchError, resetTransientAttempts } from './fetcher';

describe('fetcher', () => {
  beforeEach(() => {
    resetTransientAttempts();
  });

  it('successfully fetches data from a valid URL', async () => {
    const url = 'https://api.example.com/items';
    const result = await fetchUrl(url);

    expect(result).toBeDefined();
    expect(result.status).toBe(200);
    expect(result.url).toBe(url);

    const parsed = JSON.parse(result.data);
    expect(parsed.name).toBe('Sample Payload');
    expect(parsed.id).toBe(1);
    expect(parsed.url).toBe(url);
  });

  it('retries on 503 and recovers successfully', async () => {
    const onRetry = vi.fn();
    const url = 'https://api.example.com/transient-503-service';

    const result = await fetchUrl(url, {
      failAttempts: 1,
      backoffMs: 5,
      onRetry,
    });

    expect(result.status).toBe(200);
    expect(onRetry).toHaveBeenCalledTimes(1);
    expect(onRetry).toHaveBeenCalledWith(1, expect.any(FetchError));
    const retryError = onRetry.mock.calls[0][1] as FetchError;
    expect(retryError.status).toBe(503);
  });

  it('gives up after 3 retries on persistent 503 error', async () => {
    const onRetry = vi.fn();
    const url = 'https://api.example.com/503-service';

    try {
      await fetchUrl(url, {
        retries: 3,
        backoffMs: 5,
        onRetry,
      });
      expect.fail('Should have thrown FetchError');
    } catch (err) {
      expect(err).toBeInstanceOf(FetchError);
      const fetchErr = err as FetchError;
      expect(fetchErr.status).toBe(503);
      expect(fetchErr.url).toBe(url);
      expect(onRetry).toHaveBeenCalledTimes(3);
    }
  });

  it('handles request timeout properly', async () => {
    const url = 'https://api.example.com/timeout';

    try {
      await fetchUrl(url, {
        timeoutMs: 25,
        retries: 0,
      });
      expect.fail('Should have timed out');
    } catch (err) {
      expect(err).toBeInstanceOf(FetchError);
      const fetchErr = err as FetchError;
      expect(fetchErr.status).toBe(408);
      expect(fetchErr.message).toMatch(/timeout/i);
      expect(fetchErr.url).toBe(url);
    }
  });
});

import { describe, it, expect } from 'vitest';
import { transformData, TransformError } from './transformer';
import { FetchResult } from './types';

describe('transformer', () => {
  it('successfully transforms valid fetch result', async () => {
    const fetchResult: FetchResult = {
      url: 'https://api.example.com/items/101',
      status: 200,
      data: JSON.stringify({ id: 101, name: 'Super Awesome Widget' }),
    };

    const result = await transformData(fetchResult);

    expect(result).toBeDefined();
    expect(result.id).toBe(101);
    expect(result.slug).toBe('super-awesome-widget');
    expect(result.sourceUrl).toBe('https://api.example.com/items/101');
    expect(result.transformedAt).toBeDefined();
    expect(new Date(result.transformedAt).getTime()).not.toBeNaN();
  });

  it('generates fallback id when id is omitted', async () => {
    const fetchResult: FetchResult = {
      url: 'https://api.example.com/items/new',
      status: 200,
      data: JSON.stringify({ name: 'New Item Without ID' }),
    };

    const result = await transformData(fetchResult);
    expect(typeof result.id).toBe('number');
    expect(result.id).toBeGreaterThan(0);
    expect(result.slug).toBe('new-item-without-id');
  });

  it('fails with TransformError on missing required field', async () => {
    const fetchResult: FetchResult = {
      url: 'https://api.example.com/items/missing-name',
      status: 200,
      data: JSON.stringify({ id: 5 }),
    };

    try {
      await transformData(fetchResult);
      expect.fail('Should have thrown TransformError');
    } catch (err) {
      expect(err).toBeInstanceOf(TransformError);
      const transErr = err as TransformError;
      expect(transErr.field).toBe('name');
      expect(transErr.fieldName).toBe('name');
      expect(transErr.expectedType).toBe('string');
      expect(transErr.message).toContain('Missing required field: name');
    }
  });

  it('fails with TransformError on field type mismatch', async () => {
    // Non-string name
    const invalidNameResult: FetchResult = {
      url: 'https://api.example.com/items/invalid-name-type',
      status: 200,
      data: JSON.stringify({ id: 10, name: 9999 }),
    };

    try {
      await transformData(invalidNameResult);
      expect.fail('Should have thrown TransformError for non-string name');
    } catch (err) {
      expect(err).toBeInstanceOf(TransformError);
      const transErr = err as TransformError;
      expect(transErr.field).toBe('name');
      expect(transErr.expectedType).toBe('string');
    }

    // Non-number id
    const invalidIdResult: FetchResult = {
      url: 'https://api.example.com/items/invalid-id-type',
      status: 200,
      data: JSON.stringify({ id: 'ten', name: 'Valid Name' }),
    };

    try {
      await transformData(invalidIdResult);
      expect.fail('Should have thrown TransformError for non-number id');
    } catch (err) {
      expect(err).toBeInstanceOf(TransformError);
      const transErr = err as TransformError;
      expect(transErr.field).toBe('id');
      expect(transErr.expectedType).toBe('number');
    }
  });

  it('handles null and empty payload edge cases properly', async () => {
    // 1. JSON null payload
    const nullPayloadResult: FetchResult = {
      url: 'https://api.example.com/items/null',
      status: 200,
      data: 'null',
    };
    await expect(transformData(nullPayloadResult)).rejects.toThrow(TransformError);

    // 2. Field with explicit null value
    const nullFieldResult: FetchResult = {
      url: 'https://api.example.com/items/null-field',
      status: 200,
      data: JSON.stringify({ id: 10, name: null }),
    };

    try {
      await transformData(nullFieldResult);
      expect.fail('Should have thrown TransformError');
    } catch (err) {
      expect(err).toBeInstanceOf(TransformError);
      const transErr = err as TransformError;
      expect(transErr.field).toBe('name');
      expect(transErr.expectedType).toBe('string');
    }

    // 3. Null or undefined data string
    const nullDataResult = {
      url: 'https://api.example.com/items/null-data',
      status: 200,
      data: null as unknown as string,
    };
    await expect(transformData(nullDataResult)).rejects.toThrow(TransformError);
  });
});

import { describe, it, expect } from 'vitest';
import { loadRecord, LoadError } from './loader';
import { TransformResult } from './types';

describe('loader', () => {
  const sampleRecord: TransformResult = {
    id: 100,
    slug: 'sample-record',
    sourceUrl: 'https://api.example.com/items/100',
    transformedAt: new Date().toISOString(),
  };

  it('successfully loads record into database table', async () => {
    const result = await loadRecord('analytics_events', sampleRecord);

    expect(result).toBeDefined();
    expect(result.success).toBe(true);
    expect(result.insertedId).toBe(100);
    expect(result.table).toBe('analytics_events');
  });

  it('fails with LoadError on duplicate key violation', async () => {
    const duplicateRecord: TransformResult = {
      ...sampleRecord,
      id: -1,
    };

    try {
      await loadRecord('analytics_events', duplicateRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('analytics_events');
      expect(loadErr.tableName).toBe('analytics_events');
      expect(loadErr.operation).toBe('insert');
      expect(loadErr.message).toContain('Duplicate key violation');
      expect(loadErr.message).toContain('-1');
    }
  });

  it('fails with LoadError on database connection error', async () => {
    try {
      await loadRecord('connection_error_table', sampleRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('connection_error_table');
      expect(loadErr.operation).toBeDefined();
      expect(loadErr.message).toMatch(/connection error/i);
    }

    // Also verify via simulateConnectionError option
    try {
      await loadRecord('users', sampleRecord, { simulateConnectionError: true });
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('users');
      expect(loadErr.message).toMatch(/connection error/i);
    }
  });

  it('fails with LoadError on missing table name', async () => {
    try {
      await loadRecord('', sampleRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.message).toContain('Missing destination table name');
    }
  });
});

