### Refactoring Complete

#### 1. Shared Types & Typed Errors (`src/data-pipeline/types.ts`)
Created `src/data-pipeline/types.ts` defining all pipeline contracts and typed error classes:
- **`FetchResult`**: `{ url: string; status: number; data: string }`
- **`TransformResult`**: `{ id: number; slug: string; sourceUrl: string; transformedAt: string }`
- **`LoadResult`**: `{ insertedId: number; table: string; success: boolean }`
- **`PipelineConfig`**: `{ url: string; tableName: string }`
- **`PipelineResult`**: `{ fetch: FetchResult; transform: TransformResult; load: LoadResult }`
- **`PipelineStage`**: `'fetch' | 'transform' | 'load' | 'pipeline'`
- **`PipelineError`**: Base error class extending `Error` with `stage: PipelineStage` and `cause?: unknown`.
- **`PipelineStageError`**: Subclass of `PipelineError` preserving stage-specific context and underlying causes.
- Specialized stage errors: **`FetchError`** (`url`, `status`), **`TransformError`** (`field`, `expectedType`), and **`LoadError`** (`table`, `operation`).

---

#### 2. Modernized Sequential Pipeline (`src/data-pipeline/pipeline.ts`)
Replaced nested callback hell with a linear `async/await` chain returning `Promise<PipelineResult>` with structured error boundaries:

```ts
import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  PipelineStageError,
  FetchResult,
  TransformResult,
  LoadResult,
  FetchError,
  TransformError,
  LoadError,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError, PipelineStageError };

export async function runPipeline(
  config: PipelineConfig
): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    if (err instanceof FetchError) {
      throw new PipelineStageError(
        `Fetch stage failed for URL "${err.url}" (status ${err.status}): ${err.message}`,
        'fetch',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    if (err instanceof TransformError) {
      throw new PipelineStageError(
        `Transform stage failed for field "${err.field}" (expected ${err.expectedType}): ${err.message}`,
        'transform',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    if (err instanceof LoadError) {
      throw new PipelineStageError(
        `Load stage failed for table "${err.table}" during operation "${err.operation}": ${err.message}`,
        'load',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}

export const pipeline = runPipeline;
```

